void check(Solution& solution) {
    assert(solution.maximumLength("zzzzzzzzz") == vector<int>7);
    assert(solution.maximumLength("aaabbbccc") == vector<int>1);
    assert(solution.maximumLength("aabbbcccaaa") == vector<int>2);
    assert(solution.maximumLength("abcdef") == vector<int>-1);
    assert(solution.maximumLength("abacabadabacaba") == vector<int>1);
    assert(solution.maximumLength("abcabcabc") == vector<int>1);
    assert(solution.maximumLength("abcaba") == vector<int>1);
    assert(solution.maximumLength("aaaaabbbbccccc") == vector<int>3);
    assert(solution.maximumLength("aabbaabbcc") == vector<int>1);
    assert(solution.maximumLength("aaaaaaaaaa") == vector<int>8);
    assert(solution.maximumLength("aaaabbbbcccc") == vector<int>2);
    assert(solution.maximumLength("abababababa") == vector<int>1);
    assert(solution.maximumLength("abcdabcabcd") == vector<int>1);
    assert(solution.maximumLength("aabbccddeeefff") == vector<int>1);
    assert(solution.maximumLength("aabbccddeeffgg") == vector<int>-1);
    assert(solution.maximumLength("aaaa") == vector<int>2);
    assert(solution.maximumLength("aaabaaa") == vector<int>2);
    assert(solution.maximumLength("aaaaabbbbbaaaa") == vector<int>4);
    assert(solution.maximumLength("nnnhaaaannn") == vector<int>2);
    assert(solution.maximumLength("zzzzz") == vector<int>3);
    assert(solution.maximumLength("aabbaabbccddccddc") == vector<int>1);
    assert(solution.maximumLength("aabbccddeeffgghhiijjkkllmmnnooppqqrrssttuuvvwwxxyyzz") == vector<int>-1);
}

